//! Stable library entry points for the codegen pipeline.
//!
//! The thin `codegraph` binary delegates to these functions, and consumer
//! wrapper binaries (generated by `codegraph init` as `{name}-graph`) call
//! them directly instead of forking the generate modules.
//!
//! This file is the public facade (issue #780): the workflows live in
//! [`workflows`], and each pipeline stage has its own module —
//!
//! | Module | Owns |
//! |---|---|
//! | `args` / `outcome` | the public argument and result types |
//! | `config_files` | loading `domains.toml`, `classifier.toml` and the sibling config files |
//! | `sources` | the model-source inputs a run ingests |
//! | `graph_cache` | the persisted-graph cache (inputs hash, reuse, persistence) |
//! | `profile` | `BuildPlan` + `ProjectConfig` resolution, the dependency-pin chain |
//! | `ingestion` | the ingest passes per plane (models, designs, IFML, classification) |
//! | `generation` | template engine, ux-rules, component mappings, generation inputs |
//! | `validation` | the pre-generation gates |
//! | `post_generation` | post-gen scripts and the `--check` compile gate |
//! | `diagnostics` | notices, report printing, perf counters |

mod args;
mod config_files;
mod diagnostics;
mod generation;
mod graph_cache;
mod ingestion;
mod outcome;
mod post_generation;
mod profile;
mod sources;
mod validation;
mod workflows;

